/**
 * A settings row: label and description beside one control (`design/components/settings-row.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/settings-row.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createUniqueId, type JSX } from 'solid-js'

import { claimSlot, createDerived, resolveSlot, scope } from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/settings-row.module.css'
import type { SettingsRowGroupProps } from './SettingsRowGroup'

export type SettingsGroupProps = SettingsRowGroupProps

export interface SettingsRowProps {
  /**
   * Exactly one governed control: Switch, Select, Checkbox or Button.
   */
  control: JSX.Element
  description?: string
  label: string
}

/** A settings row: label and description beside one control. */
export default function SettingsRow(given: SettingsRowProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    const uid = createUniqueId()
    const controlSlot = resolveSlot(
      () => props.control,
      () => ({
        'aria-labelledby': labelId.value,
        'aria-describedby': props.description === undefined ? undefined : descriptionId.value,
      }),
    )
    const labelId = createDerived(() => `${uid}-label`)
    const descriptionId = createDerived(() => `${uid}-description`)
    return (
      <div class={styles.row} data-member="settings-row">
        <div class={styles.text}>
          <span class={styles.label} id={labelId.value}>
            {props.label}
          </span>
          {props.description !== undefined ? (
            <span class={styles.description} id={descriptionId.value}>
              {props.description}
            </span>
          ) : null}
        </div>
        <div class={styles.control}>{controlSlot()}</div>
      </div>
    )
  })
}
